13	// cutlass::arch::NamedBarrier::sync/arrive are only enabled Sm90 even though they work
14	// for Sm80 as well. We reimplement them here, enabled for both Sm90 and Sm80.
15	
16	CUTLASS_DEVICE
17	static void named_barrier_sync(uint32_t num_threads, uint32_t barrier_id_) {
18	    static constexpr uint32_t ReservedNamedBarrierCount = static_cast<uint32_t>(cutlass::arch::ReservedNamedBarriers::FirstUserBarrier);
19	    uint32_t barrier_id = barrier_id_ + ReservedNamedBarrierCount;
20	    asm volatile("bar.sync %0, %1;" : : "r"(barrier_id), "r"(num_threads));
21	    cutlass::arch::synclog_emit_named_barrier_arrive_and_wait(__LINE__, num_threads, barrier_id);
22	}
23	
24	CUTLASS_DEVICE
25	static void named_barrier_sync(uint32_t num_threads, cutlass::arch::ReservedNamedBarriers reserved_named_barriers) {
26	    uint32_t barrier_id = static_cast<uint32_t>(reserved_named_barriers);
27	    asm volatile("bar.sync %0, %1;" : : "r"(barrier_id), "r"(num_threads));
28	    cutlass::arch::synclog_emit_named_barrier_arrive_and_wait(__LINE__, num_threads, barrier_id);
29	}
