31	CUTLASS_DEVICE
32	static void named_barrier_arrive(uint32_t num_threads, uint32_t barrier_id_) {
33	    static constexpr uint32_t ReservedNamedBarrierCount = static_cast<uint32_t>(cutlass::arch::ReservedNamedBarriers::FirstUserBarrier);
34	    uint32_t barrier_id = barrier_id_ + ReservedNamedBarrierCount;
35	    cutlass::arch::synclog_emit_named_barrier_arrive(__LINE__, num_threads, barrier_id);
36	    asm volatile("bar.arrive %0, %1;" : : "r"(barrier_id), "r"(num_threads));
37	}
