40	static void named_barrier_arrive(uint32_t num_threads, cutlass::arch::ReservedNamedBarriers reserved_named_barriers) {
41	    uint32_t barrier_id = static_cast<uint32_t>(reserved_named_barriers);
42	    cutlass::arch::synclog_emit_named_barrier_arrive(__LINE__, num_threads, barrier_id);
43	    asm volatile("bar.arrive %0, %1;" : : "r"(barrier_id), "r"(num_threads));
