1484	        auto wg_mma_pv = tiled_mma_pv.get_slice(warp_group_thread_layout(warp_group_idx));
1485	
1486	        // Allocate "fragments/descriptors"
1487	        Tensor tOrV = wg_mma_pv.partition_fragment_B(sV);
1488	        Tensor tOsP = wg_mma_pv.partition_fragment_A(sP);
1489	
1490	        // For load scales to smem, pretend thread_idx is thread_idx % 128
1491	        auto thread_mma_pv = tiled_mma_pv.get_thread_slice(thread_idx % cutlass::NumThreadsPerWarpGroup);
1492	        Tensor taccOcO = thread_mma_pv.partition_C(cute::make_identity_tensor(select<0, 1>(TileShape_MNK_PV{})));
1493	        Tensor taccOcO_rowcol = make_tensor(taccOcO.data(), flash::convert_layout_acc_rowcol(taccOcO.layout()));
1494	        Tensor taccOcO_row = taccOcO_rowcol(_, _0{});
1495	        auto load_scales = [&](auto& scales, int stage) {
1496	            static_assert(CUTE_STATIC_V(size(scales)) == CUTE_STATIC_V(size(taccOcO_row)));
1497	            #pragma unroll
1498	            for (int mi = 0; mi < size(taccOcO_row); ++mi) {
1499	                scales(mi) = sScale(get<0>(taccOcO_row(mi)), stage);
1500	            }
1501	        };
1502	
1503	        // clear(tOrO);
1504	        // tiled_mma_pv.accumulate_ = GMMA::ScaleOut::Zero;
1505	
1506	        typename Softmax::TensorT scores_scale;
1507	
1508	        int n_block = n_block_max - 1;
1509	        // If HasQv, then by the time P is ready, V must have been ready as well
1510	        if constexpr (!HasQv) { pipeline_v.consumer_wait(smem_pipe_read); }
1511	        cutlass::arch::NamedBarrier::sync(NumMmaThreads, static_cast<uint32_t>(FwdNamedBarriers::PFull) /*id*/);
1512	        flash::gemm</*zero_init=*/true, /*wg_wait=*/0>(tiled_mma_pv, tOsP, tOrV(_, _, _, smem_pipe_read.index()), tOrO);
1513	        cutlass::arch::NamedBarrier::arrive(NumMmaThreads, static_cast<uint32_t>(FwdNamedBarriers::PEmpty) /*id*/);
1514	        pipeline_v.consumer_release(smem_pipe_read);  // release V
1515	        --n_block;
1516	
1517	        #pragma unroll 1
1518	        for (; n_block >= n_block_min; --n_block) {
1519	            cutlass::arch::NamedBarrier::sync(NumMmaThreads, static_cast<uint32_t>(FwdNamedBarriers::PFull) /*id*/);
1520	            load_scales(scores_scale, smem_pipe_read.index());
1521	            softmax.rescale_o(tOrO, scores_scale);
1522	            ++smem_pipe_read;
1523	            if constexpr (!HasQv) {
1524	                auto barrier_token = pipeline_v.consumer_try_wait(smem_pipe_read);
1525	                pipeline_v.consumer_wait(smem_pipe_read, barrier_token);
1526	            }
1527	            flash::gemm</*zero_init=*/false, /*wg_wait=*/0>(tiled_mma_pv, tOsP, tOrV(_, _, _, smem_pipe_read.index()), tOrO);
1528	            cutlass::arch::NamedBarrier::arrive(NumMmaThreads, static_cast<uint32_t>(FwdNamedBarriers::PEmpty) /*id*/);
1529	            pipeline_v.consumer_release(smem_pipe_read);  // release V
1530	        };
1531	        cutlass::arch::NamedBarrier::sync(NumMmaThreads, static_cast<uint32_t>(FwdNamedBarriers::PFull) /*id*/);
1532	        load_scales(scores_scale, smem_pipe_read.index());
1533	        cutlass::arch::NamedBarrier::arrive(NumMmaThreads, static_cast<uint32_t>(FwdNamedBarriers::PEmpty) /*id*/);
1534	        softmax.rescale_o(tOrO, scores_scale);
1535	        if constexpr (Is_FP8 && !V_colmajor) { flash::permute_output_fp8(tOrO); }
1536	        ++smem_pipe_read;
1537	        return true;
1538	    }
