181	    CUTLASS_DEVICE
182	    void
183	    operator()(Params const& params, char* smem_buf) {
184	
185	        static constexpr int NumMmaThreads = NumMmaWarpGroups * cutlass::NumThreadsPerWarpGroup;
186	        static constexpr int MmaThreadOffset = NumLoadWarpGroups * cutlass::NumThreadsPerWarpGroup;
187	        static constexpr int kBlockM = get<0>(TileShape_MNK_PV{});
188	
189	        using MainloopPipelineK = typename CollectiveMainloop::MainloopPipelineK;
190	        using MainloopPipelineV = typename CollectiveMainloop::MainloopPipelineV;
191	        using MainloopPipelineVt = typename CollectiveMainloop::MainloopPipelineVt;
192	        using MainloopPipelineKVNew = typename CollectiveMainloop::MainloopPipelineKVNew;
193	        using PipelineState = typename CollectiveMainloop::PipelineState;
194	        using PipelineParamsK = typename MainloopPipelineK::Params;
195	        using PipelineParamsV = typename MainloopPipelineV::Params;
196	        using PipelineParamsVt = typename MainloopPipelineVt::Params;
197	        using PipelineParamsKVNew = typename MainloopPipelineKVNew::Params;
198	
199	        SharedStorage& shared_storage = *reinterpret_cast<SharedStorage*>(smem_buf);
200	
201	        int const lane_predicate = cute::elect_one_sync();
202	        int const warp_idx = cutlass::canonical_warp_idx_sync();
203	
204	        // Issue Tma Descriptor Prefetch from a single thread
205	        if (warp_idx == 0 && lane_predicate) {
206	            CollectiveMainloop::prefetch_tma_descriptors(params.mainloop);
207	            CollectiveEpilogue::prefetch_tma_descriptors(params.epilogue);
208	        }
209	
210	        // Obtain warp index
211	        int const warp_group_thread_idx = threadIdx.x % cutlass::NumThreadsPerWarpGroup;
212	        int warp_group_idx = cutlass::canonical_warp_group_idx();
213	
214	        if (warp_idx == 0 && lane_predicate) {
215	            shared_storage.pipelines.barrier_Q.init(Use_TMA_Q ? 1 : NumProducerThreads /*numThreads*/);
216	            if constexpr (HasQv) {
217	                shared_storage.pipelines.barrier_Qv.init(Use_TMA_Q ? 1 : NumProducerThreads /*numThreads*/);
218	            }
219	            shared_storage.pipelines.barrier_O.init(size(ClusterShape{}) * (Use_TMA_O ? 1 : NumMmaThreads) /*numThreads*/);
220	        }
221	
222	        // We're counting on pipeline_k to call cutlass::arch::fence_barrier_init();
223	        PipelineParamsK pipeline_params_k;
224	        pipeline_params_k.role = warp_group_idx == 0
225	            ? MainloopPipelineK::ThreadCategory::Producer
226	            : MainloopPipelineK::ThreadCategory::Consumer;
227	        if constexpr (Use_TMA_KV) {
228	            pipeline_params_k.transaction_bytes = CollectiveMainloop::TmaTransactionBytesK;
229	            pipeline_params_k.is_leader = warp_group_thread_idx == 0;
230	            pipeline_params_k.num_consumers = !LargeHeadDimV ? NumMmaThreads : cutlass::NumThreadsPerWarpGroup;
231	        } else {
232	            pipeline_params_k.consumer_arv_count = !LargeHeadDimV ? NumMmaThreads : cutlass::NumThreadsPerWarpGroup;
233	            pipeline_params_k.producer_arv_count = NumProducerThreads;
234	        }
235	
236	        static_assert(is_same_v<PipelineParamsK, PipelineParamsVt>);
237	        PipelineParamsVt pipeline_params_vt = pipeline_params_k;
238	        if constexpr (Use_TMA_KV && !SameHeadDim) {
239	            pipeline_params_vt.transaction_bytes = CollectiveMainloop::TmaTransactionBytesV;
240	            if constexpr (LargeHeadDimV) { pipeline_params_vt.num_consumers = NumMmaThreads; }
241	        } else {
242	            if constexpr (LargeHeadDimV) { pipeline_params_vt.consumer_arv_count = NumMmaThreads; }
243	        }
244	
245	        MainloopPipelineK pipeline_k = [&] {
246	            if constexpr (Use_TMA_KV) {
247	                return MainloopPipelineK(shared_storage.pipelines.pipeline_k, pipeline_params_k, ClusterShape{});
248	            } else {
249	                return MainloopPipelineK(shared_storage.pipelines.pipeline_k, pipeline_params_k);
250	            }
251	        }();
252	        // MainloopPipelineV pipeline_v(shared_storage.pipelines.pipeline_v, pipeline_params_v, ClusterShape{});
253	        MainloopPipelineV pipeline_v = [&] {
254	            if constexpr (!Transpose_V) {
255	                static_assert(is_same_v<PipelineParamsK, PipelineParamsV>);
256	                if constexpr (Use_TMA_KV) {
257	                    return MainloopPipelineV(shared_storage.pipelines.pipeline_v, pipeline_params_vt, ClusterShape{});
258	                } else {
259	                    return MainloopPipelineV(shared_storage.pipelines.pipeline_v, pipeline_params_vt);
260	                }
261	            } else {
262	                PipelineParamsV pipeline_params_v;
263	                pipeline_params_v.role = warp_group_idx == 0
264	                    ? MainloopPipelineV::ThreadCategory::Producer
265	                    : MainloopPipelineV::ThreadCategory::Consumer;
266	                pipeline_params_v.producer_arv_count = NumProducerThreads;
267	                pipeline_params_v.consumer_arv_count = NumMmaThreads;
268	                return MainloopPipelineV(shared_storage.pipelines.pipeline_v, pipeline_params_v);
269	            }
270	        }();
271	        // If we need to transpose V (e.g. FP8 and V is row-major), we use pipeline_vt for the TMA, then
272	        // the producer WG will read from pipeline_vt and write to pipeline_v.
273	        // If we don't need to transpose V, we use pipeline_v for the TMA, and pipeline_vt won't be used.
274	        // Technically for pipeline_params_vt, warp0 of WG0 is the producer and all of WG0 are consumers.
275	        // However, the thread role isn't used in the pipeline implementation.
276	        MainloopPipelineVt pipeline_vt = [&] {
277	            if constexpr (Use_TMA_KV) {
278	                pipeline_params_vt.num_consumers = NumProducerThreads; // TMA_V is only consumed by the producer WG
279	                return MainloopPipelineVt(shared_storage.pipelines.pipeline_vt, pipeline_params_vt, ClusterShape{});
280	            } else {
281	                pipeline_params_vt.consumer_arv_count = NumProducerThreads; // TMA_V is only consumed by the producer WG
282	                return MainloopPipelineVt(shared_storage.pipelines.pipeline_vt, pipeline_params_vt);
283	            }
284	        }();
285	
286	        PipelineParamsKVNew pipeline_params_kv_new;
287	        pipeline_params_kv_new.role = warp_group_idx == 0
288	            ? MainloopPipelineKVNew::ThreadCategory::Producer
289	            : MainloopPipelineKVNew::ThreadCategory::Consumer;
290	        pipeline_params_kv_new.transaction_bytes = CollectiveMainloop::TmaTransactionBytesK;
291	        pipeline_params_kv_new.is_leader = warp_group_thread_idx == 0;
292	        pipeline_params_kv_new.num_consumers = NumMmaThreads;
293	        auto pipeline_k_new = cute::conditional_return<AppendKV>(MainloopPipelineKVNew(shared_storage.pipelines.pipeline_k_new, pipeline_params_kv_new, ClusterShape{}), nullptr);
294	        if constexpr (!SameHeadDim) {
295	            pipeline_params_kv_new.transaction_bytes = CollectiveMainloop::TmaTransactionBytesV;
296	        }
297	        auto pipeline_v_new = cute::conditional_return<AppendKV>(MainloopPipelineKVNew(shared_storage.pipelines.pipeline_v_new, pipeline_params_kv_new, ClusterShape{}), nullptr);
298	
299	        CollectiveMainloop mainloop;
300	        CollectiveEpilogue epilogue;
301	
302	        const int num_heads = get<2>(params.mainloop.shape_Q);
303	        Tensor gS_aux = make_tensor(make_gmem_ptr(params.mainloop.ptr_S_aux), make_shape(num_heads));
304	        Tensor sS_aux = make_tensor(make_smem_ptr(shared_storage.tensors.mainloop.smem_s_aux.data()), SmemLayoutSAux{});
305	
306	        if(params.mainloop.ptr_S_aux && threadIdx.x < num_heads) {
307	            sS_aux(threadIdx.x) = gS_aux(threadIdx.x);
308	        }
309	
310	        // We need this to guarantee that the Pipeline init is visible to all producers and consumer blocks in the Cluster
311	        if constexpr (size(ClusterShape{}) > 1) {
312	            cute::cluster_arrive_relaxed();
313	            cute::cluster_wait();
314	        } else {
315	            __syncthreads();
316	        }
317	
318	        TileScheduler scheduler(reinterpret_cast<typename TileScheduler::SharedStorage*>(&shared_storage.pipelines.smem_scheduler));
319	
320	        if (warp_group_idx == 0) {  // Producer
321	            cutlass::arch::warpgroup_reg_dealloc<LoadRegisterRequirement>();
322	
323	            // The pipelines for AppendKV and main attention are different, since e.g. main attention
324	            // might use cp.async to load KV (if PagedKVNonTMA) while AppendKV always uses TMA to load
325	            // KV_new. Since the pipeline states are different, we have to manually sync to make
326	            // sure the two pipelines don't race when accessing smem_k and smem_v.
327	            PipelineState smem_pipe_write = cutlass::make_producer_start_state<MainloopPipelineK>();
328	            PipelineState smem_pipe_write_new = cutlass::make_producer_start_state<MainloopPipelineKVNew>();
329	            int work_idx = 0;
330	            int warp_idx_in_warpgroup = __shfl_sync(0xffffffff, (threadIdx.x / 32) % 4, 0);
331	            static constexpr bool SingleProducerWarp = NumProducerThreads == cutlass::NumThreadsPerWarp;
332	            if constexpr (SingleProducerWarp) {
333	                if (warp_idx_in_warpgroup != 0) { return; }
334	            }
335	            if (!SingleProducerWarp && warp_idx_in_warpgroup != 0) { scheduler.init_consumer(); }
336	
337	            cutlass::arch::wait_on_dependent_grids();
